Map<String, dynamic>? _baselineCache;
Map<String, dynamic> get _baseline =>
    _baselineCache ??= Map<String, dynamic>.from(
      jsonDecode(
            _compiledBaselineBase64.isNotEmpty
                ? utf8.decode(
                    gzip.decode(base64Decode(_compiledBaselineBase64)),
                  )
                : File(_baselinePath).readAsStringSync(),
          )
          as Map,
    );

Object? _canonical(Object? value) {
  if (value is Map) {
    final keys = value.keys.cast<String>().toList()..sort();
    return {for (final key in keys) key: _canonical(value[key])};
  }
  if (value is List) return value.map(_canonical).toList();
  return value;
}

String _digest(Object? value) =>
    sha256.convert(utf8.encode(jsonEncode(_canonical(value)))).toString();

String _words(Object? value) =>
    (value?.toString() ?? '').replaceAll(RegExp(r'\s+'), ' ').trim();

Map<String, dynamic> _identity(
  AuthoredCollection collection,
  Map<String, dynamic> document,
) => {
  'catalogId': collection.bundledId,
  'productKey': pointShopAuthoredTemplateKey(collection),
  'price':
      pointShopLaunchPrices[pointShopAuthoredTemplateKey(collection)]!.points,
  for (final key in const [
    'id',
    'collectionId',
    'editionId',
    'title',
    'category',
    'aiGenerated',
    'accessTier',
    'publicationStatus',
    'innerPageCount',
    'aspect',
    'designWidth',
    'designHeight',
    'chapters',
  ])
    if (document.containsKey(key)) key: document[key],
};

Map<String, dynamic> _sources(Map layer) {
  final fields = <String, dynamic>{
    for (final key in const ['imageUrl', 'originalUrl', 'previewUrl'])
      if (layer.containsKey(key)) key: layer[key],
  };
  if (layer.containsKey('editorialSourceImageUrl')) {
    // One audited sample was mislabeled: it shows a person rather than a room.
    // Normalize only this exact approved substitution. Other source fields and
    // each photo ID remain part of the immutable recorded source digest.
    if (layer['editorialSourceImageUrl'] != _incorrectRoomSample ||
        fields['imageUrl'] != _approvedRoomSample) {
      throw StateError(
        'Unapproved editorial sample substitution: ${layer['id']}',
      );
    }
    fields['imageUrl'] = _incorrectRoomSample;
  }
  return fields;
}

Map<String, dynamic> _pageRecord(Map<String, dynamic> page) {
  final layers = (page['layers'] as List).cast<Map>();
  return {
    'page': _digest(page),
    'visual': _digest([
      for (final layer in layers)
        {
          for (final key in const [
            'id',
            'type',
            'x',
            'y',
            'w',
            'h',
            'rotation',
            'frame',
            'align',
            'style',
            'fillColor',
            'opacity',
            'cornerRadius',
            'fontFamily',
            'fontSize',
            'fontWeight',
            'lineHeight',
          ])
            if (layer.containsKey(key)) key: layer[key],
        },
    ]),
    'ids': {for (final layer in layers) layer['id'] as String: layer['type']},
    'text': {
      for (final layer in layers.where((l) => l['type'] == 'text'))
        layer['id'] as String: {
          'exact': _digest(layer['editorialSourceText'] ?? layer['text']),
          'words': _digest(
            _words(layer['editorialSourceText'] ?? layer['text']),
          ),
          'display': _digest(_words(layer['text'])),
        },
    },
    'photos': {
      for (final layer in layers.where((l) => l['type'] == 'image'))
        layer['id'] as String: _digest(_sources(layer)),
    },
  };
}

/// Preserve the authored archive recorded before the free catalog revision.
/// Current paid catalog refinements have a separate source/identity contract.
Map<String, dynamic> _archivedPaidCatalog(
  Map<String, dynamic> Function(CollectionAspect) build,
) => {
  ...build(CollectionAspect.square),
  'variants': {
    for (final aspect in CollectionAspect.values) aspect.name: build(aspect),
  },
};

String _paidDigest() => _digest({
  'catalogs': {
    for (final entry in premiumVolumeCatalogIds.entries)
      entry.value.toString(): _archivedPaidCatalog(entry.key.document),
    for (final entry in conceptVolumeCatalogIds.entries)
      entry.value.toString(): _archivedPaidCatalog(entry.key.document),
    for (final edition in AtelierEdition.values)
      edition.catalogId.toString(): _archivedPaidCatalog(edition.document),
    for (final edition in StudioEdition.values.where((e) => e.premium))
      edition.catalogId.toString(): _archivedPaidCatalog(edition.document),
  },
  'editions': {
    for (final volume in PremiumVolume.values)
      volume.id: {
        for (final count in volume.pageCounts)
          count.toString(): {
            for (final aspect in CollectionAspect.values)
              aspect.name: volume.document(aspect, innerPages: count),
          },
      },
  },
});

Future<void> _loadFonts() async {
  final manifest =
      jsonDecode(await rootBundle.loadString('FontManifest.json')) as List;
  for (final entry in manifest.whereType<Map>()) {
    final loader = FontLoader(entry['family'] as String);
    for (final font in (entry['fonts'] as List).whereType<Map>()) {
      loader.addFont(rootBundle.load(font['asset'] as String));
    }
    await loader.load();
    _fontFamilies.add(entry['family'] as String);
  }
}

Map<String, dynamic> _recordBaseline() => {
  'schema': 1,
  'paid': _paidDigest(),
  'books': {
    for (final collection in authoredCollections)
      collection.id: {
        for (final aspect in CollectionAspect.values)
          aspect.name: _recordBook(collection, aspect),
      },
  },
};

Map<String, dynamic> _recordBook(
  AuthoredCollection collection,
  CollectionAspect aspect,
) {
  final document = collection.document(aspect);
  return {
    'identity': _digest(_identity(collection, document)),
    'pages': [
      for (final page in templateDocumentPages(document)) _pageRecord(page),
    ],
  };
}

String _sourceDigest(Map<String, dynamic> page) {
  final record = _pageRecord(page);
  return _digest({
    'ids': {
      for (final e in (record['ids'] as Map).entries)
        if (e.value == 'image' || e.value == 'text') e.key as String: e.value,
    },
    'text': record['text'],
    'photos': record['photos'],
  });
}

String _visualWithoutFolios(Map<String, dynamic> page) => _digest([
  for (final layer in (page['layers'] as List).cast<Map>())
    if (!(layer['id'] as String).endsWith('_folio') &&
        !(layer['id'] as String).endsWith('_running_head'))
      {
        for (final key in const [
          'id',
          'type',
          'x',
          'y',
          'w',
          'h',
          'rotation',
          'frame',
          'align',
          'style',
          'fillColor',
          'opacity',
          'cornerRadius',
          'fontFamily',
          'fontSize',
          'fontWeight',
          'lineHeight',
        ])
          if (layer.containsKey(key)) key: layer[key],
      },
]);

Rect _rect(LayerModel layer) =>
    layer.position & Size(layer.width, layer.height);
Rect _paintBounds(LayerModel layer) {
  final angle = layer.rotation * math.pi / 180;
  return Rect.fromCenter(
    center: _rect(layer).center,
    width:
        layer.width * math.cos(angle).abs() +
        layer.height * math.sin(angle).abs(),
    height:
        layer.width * math.sin(angle).abs() +
        layer.height * math.cos(angle).abs(),
  );
}

bool _contains(Rect outer, Rect inner) =>
    outer.left <= inner.left + .5 &&
    outer.top <= inner.top + .5 &&
    outer.right >= inner.right - .5 &&
    outer.bottom >= inner.bottom - .5;

Color? _paper(List<LayerModel> layers, int textIndex) {
  final rect = _rect(layers[textIndex]);
  for (final behind in layers.take(textIndex).toList().reversed) {
    if (!_rect(behind).overlaps(rect)) continue;
    if (behind.type == LayerType.image ||
        (behind.type == LayerType.sticker && behind.hasImageSource))
      return null;
    final value = behind.decorationFillColor;
    if (value == null || behind.opacity != 1 || !_contains(_rect(behind), rect))
      continue;
    final hex = value.replaceFirst('#', '');
    final color = Color(int.parse(hex.length == 6 ? 'FF$hex' : hex, radix: 16));
    if (color.a == 1) return color;
  }
  return null;
}

LayerModel _roundTrip(LayerModel layer, CollectionAspect aspect, bool cover) =>
    LayerExportMapper.fromJson(
      Map<String, dynamic>.from(
        jsonDecode(
              jsonEncode(
                LayerExportMapper.toJson(
                  layer,
                  canvasSize: aspect.canvas,
                  isCover: cover,
                ),
              ),
            )
            as Map,
      ),
      canvasSize: aspect.canvas,
      isCover: cover,
    );

void _inspectPage(
  Map<String, dynamic> page,
  CollectionAspect aspect,
  int index,
  String book,
) {
  final layers = DataTemplateEngine.buildLayersFromJson(page, aspect.canvas);
  final raw = {
    for (final l in (page['layers'] as List).cast<Map>()) l['id']: l,
  };
  expect(
    layers.map((l) => l.id).toSet(),
    hasLength(layers.length),
    reason: book,
  );
  final cleared = AlbumCreationTemplate.preparePages(
    [layers],
    sourceCanvas: aspect.canvas,
    cover: aspect.cover,
  ).single;
  final photos = layers.where((l) => l.type == LayerType.image).toList();
  if (index == 0) {
    expect(photos, isNotEmpty, reason: '$book: cover photograph');
    final largest = photos
        .map((l) => l.width * l.height)
        .fold<double>(0, math.max);
    expect(
      largest / (aspect.canvas.width * aspect.canvas.height),
      greaterThanOrEqualTo(.8),
      reason: '$book: immersive hero photograph',
    );
    expect(page['coverTextTreatment'], 'open-photographic-type', reason: book);
    expect(page['typographyPanelCoverageFraction'], 0.0, reason: book);
    final photoIndex = layers.indexWhere((l) => l.type == LayerType.image);
    expect(
      layers
          .skip(photoIndex + 1)
          .where((l) => l.type != LayerType.text && l.type != LayerType.image),
      isEmpty,
      reason: '$book: open photography without type plates or scrims',
    );
  }
  for (final (layerIndex, layer) in layers.indexed) {
    final label = '$book/$index/${layer.id}';
    final rect = _rect(layer), painted = _paintBounds(layer);
    expect(rect.isFinite, isTrue, reason: label);
    expect(rect.width, greaterThan(0), reason: label);
    expect(rect.height, greaterThan(0), reason: label);
    expect(painted.left, greaterThanOrEqualTo(-.5), reason: label);
    expect(painted.top, greaterThanOrEqualTo(-.5), reason: label);
    expect(
      painted.right,
      lessThanOrEqualTo(aspect.canvas.width + .5),
      reason: label,
    );
    expect(
      painted.bottom,
      lessThanOrEqualTo(aspect.canvas.height + .5),
      reason: label,
    );
    final saved = _roundTrip(layer, aspect, index == 0);
    expect(saved.id, layer.id, reason: label);
    expect(saved.type, layer.type, reason: label);
    expect(saved.position.dx, closeTo(layer.position.dx, .001), reason: label);
    expect(saved.position.dy, closeTo(layer.position.dy, .001), reason: label);
    expect(saved.width, closeTo(layer.width, .001), reason: label);
    expect(saved.height, closeTo(layer.height, .001), reason: label);
    expect(saved.rotation, layer.rotation, reason: label);
    expect(saved.opacity, layer.opacity, reason: label);
    if (layer.type == LayerType.image) {
      expect(
        [layer.imageUrl, layer.originalUrl, layer.previewUrl],
        isNot(contains(_incorrectRoomSample)),
        reason: '$label: mislabeled portrait must not appear as a room sample',
      );
      if (raw[layer.id]!['editorialSourceImageUrl'] == _incorrectRoomSample) {
        expect(layer.imageUrl, _approvedRoomSample, reason: label);
        _approvedSampleReplacements++;
      }
      expect(saved.imageUrl, layer.imageUrl, reason: label);
      expect(saved.imageZoom, layer.imageZoom, reason: label);
      expect(
        saved.imageOffset?.dx ?? 0,
        closeTo(layer.imageOffset?.dx ?? 0, .001),
      );
      expect(
        saved.imageOffset?.dy ?? 0,
        closeTo(layer.imageOffset?.dy ?? 0, .001),
      );
      expect(cleared[layerIndex].hasImageSource, isFalse, reason: label);
      final replacement = _roundTrip(
        cleared[layerIndex].copyWith(
          imageUrl: 'asset:assets/snapfit_home_square.jpg',
        ),
        aspect,
        index == 0,
      );
      expect(replacement.imageUrl, 'asset:assets/snapfit_home_square.jpg');
      expect(replacement.imageBackground, layer.imageBackground);
    }
    if (layer.type != LayerType.text) continue;
    if (index > 0 &&
        !(book.startsWith('$windAtlasId/') &&
            _protectedWindPages.contains(index))) {
      expect(
        layer.textFillMode?.trim().toLowerCase(),
        anyOf(isNull, '', 'none', 'solid'),
        reason:
            '$label: rendered ink must match the color checked for contrast',
      );
    }
    expect(saved.text, layer.text, reason: label);
    expect(
      saved.textStyle!.fontFamily,
      layer.textStyle!.fontFamily,
      reason: label,
    );
    expect(_fontFamilies, contains(layer.textStyle!.fontFamily), reason: label);
    final role = raw[layer.id]!['typographyRole'] as String?;
    expect(role, isNotNull, reason: '$label: explicit typographic role');
    expect(
      layer.textStyle!.fontSize,
      greaterThanOrEqualTo(role == 'body' ? 11.0 : 8.5),
      reason: label,
    );
    final measure = TextPainter(
      text: TextSpan(text: layer.text, style: layer.textStyle),
      textAlign: layer.textAlign ?? TextAlign.left,
      textDirection: TextDirection.ltr,
      strutStyle: StrutStyle.fromTextStyle(
        layer.textStyle!,
        forceStrutHeight: true,
      ),
    )..layout(maxWidth: layer.width);
    expect(
      measure.height,
      lessThanOrEqualTo(layer.height + .5),
      reason: '$label: text fit',
    );
    expect(
      measure.computeLineMetrics().every((l) => l.width <= layer.width + .5),
      isTrue,
      reason: '$label: text width',
    );
    measure.dispose();
    if (index > 0) {
      final outer = aspect.canvas.width * .04,
          binding = aspect.canvas.width * .06;
      expect(
        rect.left,
        greaterThanOrEqualTo((index.isEven ? binding : outer) - .5),
        reason: '$label: left text safety',
      );
      expect(
        rect.right,
        lessThanOrEqualTo(
          aspect.canvas.width - (index.isOdd ? binding : outer) + .5,
        ),
        reason: '$label: binding text safety',
      );
      expect(rect.top, greaterThanOrEqualTo(11.5), reason: label);
      expect(
        rect.bottom,
        lessThanOrEqualTo(aspect.canvas.height - 11.5),
        reason: '$label: footer clearance',
      );
    }
    if (index == 0) {
      expect(layer.textFillMode, 'solid', reason: label);
      expect(layer.textStyle!.shadows, isNotEmpty, reason: label);
    }
    if (index > 0 && (layer.text ?? '').trim().isNotEmpty) {
      final paper = _paper(layers, layerIndex);
      expect(
        paper,
        isNotNull,
        reason: '$label: text needs a known photo-safe surface',
      );
      if (paper != null) {
        final ink = Color.alphaBlend(layer.textStyle!.color!, paper);
        final a = ink.computeLuminance(), b = paper.computeLuminance();
        expect(
          (math.max(a, b) + .05) / (math.min(a, b) + .05),
          greaterThanOrEqualTo(4.5),
          reason: '$label: text contrast',
        );
      }
    }
  }
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  setUpAll(_loadFonts);
  if (_record) {
    test('record all 126 shipping books as fixed source and identity hashes', () {
      expect(authoredCollections, hasLength(42));
      expect(publishedPremiumTemplates, hasLength(26));
      final baseline = _recordBaseline();
      final bytes = utf8.encode(jsonEncode(baseline));
      // This file contains only IDs, types and fixed hashes. No text bodies,
      // photo bytes, complete documents, preview or exported artwork are saved.
      if (File(_baselinePath).existsSync()) {
        throw StateError(
          'Refusing to replace the original recorded baseline: $_baselinePath',
        );
      }
      File(_baselinePath).writeAsBytesSync(bytes);
      // ignore: avoid_print
      print(
        'SNAPFIT_FREE_EDITORIAL_BASELINE_V1:${jsonEncode({'path': _baselinePath, 'bytes': bytes.length, 'sha256': _digest(baseline), 'books': 126, 'pages': (baseline['books'] as Map).values.fold<int>(0, (total, variants) => total + (variants as Map).values.fold<int>(0, (sum, book) => sum + ((book as Map)['pages'] as List).length))})}',
      );
    });
    return;
  }

  test('all archived paid editions remain byte-for-byte identical', () {
    expect(_paidDigest(), _baseline['paid']);
    expect(authoredCollections, hasLength(42));
    expect(publishedPremiumTemplates, hasLength(26));
  });
  test(
    'sample provenance permits only the single audited old-to-new asset pair',
    () {
      expect(
        _sources({
          'imageUrl': _approvedRoomSample,
          'editorialSourceImageUrl': _incorrectRoomSample,
        }),
        {'imageUrl': _incorrectRoomSample},
      );
      for (final forged in [
        {
          'imageUrl': 'asset:assets/another-photo.png',
          'editorialSourceImageUrl': _incorrectRoomSample,
        },
        {
          'imageUrl': _approvedRoomSample,
          'editorialSourceImageUrl': 'asset:assets/another-original.png',
        },
        {
          'imageUrl': _incorrectRoomSample,
          'editorialSourceImageUrl': _incorrectRoomSample,
        },
      ]) {
        expect(() => _sources(forged), throwsStateError);
      }
      expect(
        _sources({
          'imageUrl': _approvedRoomSample,
          'originalUrl': 'asset:assets/unapproved-original.png',
          'editorialSourceImageUrl': _incorrectRoomSample,
        }),
        {
          'imageUrl': _incorrectRoomSample,
          'originalUrl': 'asset:assets/unapproved-original.png',
        },
        reason: 'Unrelated source fields must never be normalized away.',
      );
      expect(
        _digest(
          _sources({
            'imageUrl': _approvedRoomSample,
            'editorialSourceImageUrl': _incorrectRoomSample,
          }),
        ),
        isNot(_digest({'imageUrl': _approvedRoomSample})),
        reason:
            'Provenance cannot be added to a different original photo to bypass its baseline.',
      );
    },
  );
  for (final collection in authoredCollections) {
    for (final aspect in CollectionAspect.values) {
      test(
        '${collection.id}/${aspect.name}: every page preserves content and passes print-aware quality',
        () {
          final document = collection.document(aspect);
          final book = '${collection.id}/${aspect.name}';
          final original =
              (_baseline['books'] as Map)[collection.id][aspect.name] as Map;
          expect(
            _digest(_identity(collection, document)),
            original['identity'],
            reason: book,
          );
          expect(
            pointShopRequiresFreePrice(
              pointShopAuthoredTemplateKey(collection),
            ),
            isTrue,
          );
          expect(freeTemplateMaterialIssues(document), isEmpty, reason: book);
          final pages = templateDocumentPages(document);
          final before = original['pages'] as List;
          expect(pages, hasLength(before.length), reason: book);
          for (final (index, page) in pages.indexed) {
            final source = before[index] as List;
            expect(
              _sourceDigest(page),
              source[2],
              reason: '$book/$index: original photo/text IDs and content',
            );
            final visual = _pageRecord(page)['visual'];
            final protected =
                collection.id == windAtlasId &&
                _protectedWindPages.contains(index);
            if (protected) {
              final original = templateDocumentPages(
                buildWindAtlas(aspect),
              )[index];
              // The independent source still has to match its recorded visual
              // hash. Only its footer may move to restore print clearance.
              expect(
                _pageRecord(original)['visual'],
                source[1],
                reason: '$book/$index: source study changed',
              );
              expect(
                _visualWithoutFolios(page),
                _visualWithoutFolios(original),
                reason: '$book/$index: approved photo/body/title composition',
              );
            } else {
              expect(
                visual,
                isNot(source[1]),
                reason: '$book/$index: actual visual refinement',
              );
            }
            _inspectPage(page, aspect, index, book);
            _verifiedPages++;
            if (index > 0) {
              final layout = page['editorialLayout'] as String?;
              expect(
                layout,
                isNotNull,
                reason: '$book/$index: explicit reading direction',
              );
              _layoutCounts.update(
                layout!,
                (value) => value + 1,
                ifAbsent: () => 1,
              );
              if (protected)
                _protectedInteriors++;
              else
                _refinedInteriors++;
            }
          }
        },
      );
    }
  }
  test('all 3174 pages completed the source and quality preflight', () {
    expect(_verifiedPages, 3174);
    expect(_refinedInteriors, 3030);
    expect(_protectedInteriors, 18);
    expect(
      _approvedSampleReplacements,
      105,
      reason:
          'Exactly the 105 recorded uses of the mislabeled source are replaced.',
    );
    final active = _layoutCounts.keys
        .where((k) => k != 'wind-signature-preserved')
        .toSet();
    expect(active, containsAll(_activeLayouts));
    expect(active, hasLength(_activeLayouts.length));
    // ignore: avoid_print
    print(
      'SNAPFIT_FREE_EDITORIAL_QUALITY_METRICS_V1:${jsonEncode({
        'books': 126,
        'pages': _verifiedPages,
        'covers': 126,
        'refinedInteriors': _refinedInteriors,
        'protectedInteriors': _protectedInteriors,
        'approvedSampleReplacement': {'from': _incorrectRoomSample, 'to': _approvedRoomSample, 'layers': _approvedSampleReplacements},
        'layoutCounts': _layoutCounts,
      })}',
    );
  });
}
